                z.append(x_sub.pop(0))
            else:
                z.append(y_sub.pop(0))
        if is_chaotic(z):
            chaotic_count += 1
    return chaotic_count

def main():
    x = input().strip()
    y = input().strip()

    total_sum = 0
    for l1 in range(1, len(x) + 1):
        for r1 in range(l1, len(x) + 1):
            for l2 in range(1, len(y) + 1):
                for r2 in range(l2, len(y) + 1):
                    total_sum = (total_sum + f(l1, r1, l2, r2)) % MOD

    print(total_sum)

if __name__ == "__main__":
    main()
